function trackEvent(e,t={}){window.dataLayer=window.dataLayer||[],window.dataLayer.push({event:e,...t})}document.querySelectorAll("[data-track]").forEach(e=>{e.addEventListener("click",function(){trackEvent(this.getAttribute("data-track"),{project:this.getAttribute("data-project")||"",element_text:this.textContent.trim().substring(0,50)})})}),document.querySelectorAll('a[href*="wa.me"]').forEach(e=>{e.addEventListener("click",()=>{trackEvent("whatsapp_click",{project:e.getAttribute("data-project")||"general"})})}),document.querySelectorAll('a[href^="tel:"]').forEach(e=>{e.addEventListener("click",()=>{trackEvent("phone_click",{phone_number:e.href.replace("tel:","")})})}),document.querySelectorAll('a[href^="mailto:"]').forEach(e=>{e.addEventListener("click",()=>{trackEvent("email_click",{email_address:e.href.replace("mailto:","")})})});const leadForm=document.getElementById("lead-form");leadForm&&leadForm.addEventListener("submit",function(){trackEvent("generate_lead",{form_type:"contacto",project:this.proyecto.value,interes:this.interes.value})});